import{_ as e,o,c as r,a2 as i}from"./chunks/framework.BWuWLRhz.js";const p=JSON.parse('{"title":"LocalSend (Configuración)","description":"","frontmatter":{},"headers":[],"relativePath":"es-ES/user-guide/settings/localsend.md","filePath":"es-ES/user-guide/settings/localsend.md","lastUpdated":1787586465000}'),n={name:"es-ES/user-guide/settings/localsend.md"};function t(s,a,l,d,c,u){return o(),r("div",null,[...a[0]||(a[0]=[i('<h1 id="localsend-configuracion" tabindex="-1">LocalSend (Configuración) <a class="header-anchor" href="#localsend-configuracion" aria-label="Permalink to &quot;LocalSend (Configuración)&quot;">​</a></h1><p>Lertaro incluye un motor de transmisión inalámbrica local nativamente compatible con el protocolo de código abierto <a href="https://localsend.org" target="_blank" rel="noreferrer">LocalSend</a>. Sin necesidad de internet ni cables, permite compartir archivos, carpetas y texto plano a máxima velocidad entre ordenadores Windows, Mac, Linux, iPhone, iPad y dispositivos Android en la misma red local. La página se encuentra en <strong>Configuración → LocalSend</strong>.</p><h2 id="_1-configuracion-basica-del-servicio" tabindex="-1">1. Configuración básica del servicio <a class="header-anchor" href="#_1-configuracion-basica-del-servicio" aria-label="Permalink to &quot;1. Configuración básica del servicio&quot;">​</a></h2><ul><li><strong>Habilitar transmisión LocalSend</strong>: Interruptor maestro. Al activarlo, Lertaro inicia un servicio de escucha en segundo plano y añade la opción &quot;Enviar a otros dispositivos...&quot; al menú de la bandeja del sistema.</li><li><strong>Nombre de dispositivo</strong>: El alias visible para otros dispositivos en la red local. Se genera a partir del nombre del equipo y puede cambiarse (p. ej., <code>Portátil de trabajo</code>).</li><li><strong>Puerto del servicio</strong>: Puerto de escucha HTTP/HTTPS (por defecto <code>53317</code>, estándar de LocalSend). Modificable si entra en conflicto con otros servicios.</li></ul><h2 id="_2-seguridad-cifrado-y-almacenamiento" tabindex="-1">2. Seguridad, cifrado y almacenamiento <a class="header-anchor" href="#_2-seguridad-cifrado-y-almacenamiento" aria-label="Permalink to &quot;2. Seguridad, cifrado y almacenamiento&quot;">​</a></h2><ul><li><strong>Transferencia cifrada (HTTPS)</strong>: Activado por defecto. Utiliza TLS en las comunicaciones locales para evitar interceptaciones de paquetes.</li><li><strong>Código PIN de recepción</strong>: PIN numérico opcional (4–6 dígitos). Si se activa, el emisor debe introducir el mismo PIN antes de iniciar la transferencia (dejar vacío para desactivar).</li><li><strong>Guardar archivos automáticamente</strong>: Acepta y guarda transferencias de dispositivos locales automáticamente sin requerir confirmación manual.</li><li><strong>Directorio de guardado</strong>: Carpeta de destino predeterminada para los archivos recibidos (por defecto <code>Downloads\\LocalSend</code>), personalizable mediante el botón Examinar.</li></ul><h2 id="_3-ventana-de-envio-y-flujo-de-trabajo" tabindex="-1">3. Ventana de envío y flujo de trabajo <a class="header-anchor" href="#_3-ventana-de-envio-y-flujo-de-trabajo" aria-label="Permalink to &quot;3. Ventana de envío y flujo de trabajo&quot;">​</a></h2><ul><li><strong>Invocación por atajo</strong>: Pulsa el atajo global predeterminado <strong><code>Ctrl+S</code></strong> (reasignable en <a href="./hotkeys-page.html"><strong>Configuración → Atajos de teclado</strong></a>) para abrir la ventana de envío de LocalSend.</li><li><strong>Modos de envío</strong>: Alterna fácilmente entre los modos <strong>[Enviar archivos / carpetas]</strong> y <strong>[Enviar texto]</strong> en la parte superior.</li><li><strong>Envío por arrastre</strong>: Arrastra archivos directamente desde los resultados de Lertaro, el Panel rápido o el Explorador hacia la ventana. El radar detecta automáticamente los dispositivos en línea; pulsa sobre el destinatario para transferir los archivos.</li></ul>',8)])])}const m=e(n,[["render",t]]);export{p as __pageData,m as default};
